/** Typed access to data/shipped.json, generated by scripts/generate-copy.mjs from the sync. */
import shippedData from "../../data/shipped.json";

export type ShippedItem = {
  project: string;
  slug: string;
  kind: "pr" | "tag" | "npm";
  title: string;
  date: string;
  url: string;
};

export const shipped = shippedData as ShippedItem[];

export const KIND_LABEL: Record<ShippedItem["kind"], string> = {
  pr: "Merged PR",
  tag: "Release tag",
  npm: "npm release",
};
